        public static hasBonusGame(data: number[]): boolean {
            let bgCount: number = 0;
            for (let num of data) {
                if (num >= this.BONUS_GAME_ICON_START_IDX) {
                    bgCount++;
                    if (bgCount >= this.HasBonusGameNumber) {
                        return true;
                    }
                }
            }
            return false;
        }

        public static hasFreeGame(data: number[]): boolean {
            let fgCount: number = 0;
            for (let num of data) {
                if (num === this.FREE_GAME_ICON_START_IDX) {
                    fgCount++;
                    if (fgCount >= this.HasFreeGameNumber) {
                        return true;
                    }
                }
            }
            return false;
        }

        public static splitIconList(dataList: number[], currentGameMode: GameMode): number[][] {
            let newIconList: number[][] = [];
            let currentIndex: number = 0;
            if (dataList.length >= 15) {
                for (let i = 0; i < dataList.length / this.ROW; i++) {
                    let finalIcons: number[] = dataList.slice(currentIndex * this.ROW, (currentIndex + 1) * this.ROW);
                    newIconList.push(finalIcons);
                    currentIndex++;
                }
            }
            else if (dataList.length === this.FreeGameIconListLength) {
                newIconList.push(dataList.slice(0, 3));
                newIconList.push(dataList.slice(3, 4));
                newIconList.push(dataList.slice(4, this.FreeGameIconListLength));
            }
            if (currentGameMode === GameMode.BonusGame) {
                newIconList = newIconList.flat().map(icon => [icon]);
            }
            return newIconList;
        }

        public static changeFGToNGIconList(data: number[], isToNGIconList: boolean): number[] {
            const newData: number[] = [...data];
            if (isToNGIconList) {
                const thirdElement: number = newData[3];
                newData.splice(4, 0, ...Array(8).fill(thirdElement));
            }
            else {
                newData.splice(4, 8);
            }
            return newData;
        }

