    class ServerDataSplit1014 {

        public splitData(serverData: number[]): SplitData {
            let ngResult: number[] = [];
            let bgResult: SplitBGData = null;
            let fgResult: SplitFGData[] = [];

            ngResult.push(...serverData.splice(0, Game1014Config.ROW * Game1014Config.COLUMNS));
            if (Game1014Config.hasBonusGame(ngResult)) {
                bgResult = this.splitBGData(serverData, ngResult);
            }
            if (Game1014Config.hasFreeGame(ngResult)) {
                fgResult = this.splitFGData(serverData);
            }
            return new SplitData(ngResult, bgResult, fgResult);
        }

        private splitFGData(serverData: number[]): SplitFGData[] {
            let fgResult: SplitFGData[] = [];
            let fgGameCount = Game1014Config.FGInitCount;

            for (let i = 0; i < fgGameCount; i++) {
                const data = [...serverData.splice(0, Game1014Config.FreeGameIconListLength)];
                if (Game1014Config.hasFreeGame(data) || data[Game1014Config.BigIconIndex] === Game1014Config.FREE_GAME_ICON_START_IDX) {//中間的大圖示算9個
                    fgGameCount += Game1014Config.FGAddCount;
                }
                let fgToBGResult: SplitBGData = null;
                const fgData = [...Game1014Config.changeFGToNGIconList(data, true)];
                if (Game1014Config.hasBonusGame(fgData)) {
                    fgToBGResult = this.splitBGData(serverData, fgData);
                }
                const fgToBGData = new SplitFGData(data, fgToBGResult);
                fgResult.push(fgToBGData);
            }
            return fgResult;
        }

        private splitBGData(serverData: number[], previousData: number[]): SplitBGData {
            let whileAddNumber = 0;
            let bgResult: number[][] = [];
            let currentGameIndex = Game1014Config.BGInitCount;
            let bgIconCount = previousData.reduce((count, current) => current >= Game1014Config.BONUS_GAME_ICON_START_IDX ? count + 1 : count, 0);

            while (currentGameIndex > 0) {
                if (bgIconCount >= previousData.length) {
                    return new SplitBGData(bgResult, true);
                }
                const index = serverData.indexOf(Game1014Config.BGServerNullValue);//255為結尾
                if (index > 0) {
                    const data = [...serverData.splice(0, index)];
                    bgResult.push(data);
                    serverData.splice(0, 1);
                    currentGameIndex = Game1014Config.BGReStartCount;
                    bgIconCount += data.length / 2;
                }
                else if (this.isNullBGData(index, serverData[1])) {
                    serverData.splice(0, 1);
                    bgResult.push([]);
                    currentGameIndex -= 1;
                }
                whileAddNumber++;
                if (whileAddNumber > 1000) {
                    console.error('whileAddNumber > 1000');
                    return;
                }
            }
            return new SplitBGData(bgResult, false);
        }

        private isNullBGData(index: number, nextDataNumber: number): boolean {
            const dataIsNull: boolean = index === 0;
            const nextDataNumberIsNull: boolean = nextDataNumber === Game1014Config.BGServerNullValue;
            return dataIsNull || nextDataNumberIsNull;
        }
    }

